const DEFAULT_COLLAPSED_AVATAR_SOURCE = 'data:image/png;base64,'

// Fixed built-in collapsed avatar source.
// Leave empty to use the bundled fallback image.
export const COLLAPSED_AVATAR_SOURCE = ''

function svgToDataUrl(svg: string): string {
  return `data:image/svg+xml,${encodeURIComponent(svg)}`
}

function escapeCssUrl(value: string): string {
  return value.replaceAll('\\', '\\\\').replaceAll('"', '\\"').replaceAll('\r', '').replaceAll('\n', '')
}

function cssUrl(value: string): string {
  return `url("${escapeCssUrl(value)}")`
}

export function resolveCollapsedAvatarUrl(source = COLLAPSED_AVATAR_SOURCE): string {
  const trimmed = source.trim()
  const fallback = cssUrl(DEFAULT_COLLAPSED_AVATAR_SOURCE)
  if (trimmed === '') return fallback
  if (trimmed.startsWith('data:image/')) return cssUrl(trimmed)
  if (trimmed.startsWith('<svg') || trimmed.startsWith('<?xml')) {
    return cssUrl(svgToDataUrl(trimmed))
  }
  return `${cssUrl(trimmed)}, ${fallback}`
}

export const COLLAPSED_AVATAR_URL = resolveCollapsedAvatarUrl()
